entry.content:
C++ 备忘清单提供基本语法和方法的 C++ 快速参考备忘单 入门hello.cpp#include &lt;iostream&gt;int main() &#123; std::cout &lt;&lt; &quot;Hello Quick Reference\n&quot;; return 0;&#125;
编译运行 $ g++ hello.cpp -o hello$ ./helloHello Quick Reference
变量int number = 5; // 整数float f = 0.95; // 浮点数double PI = 3.14159; // 浮点数char yes = &#x27;Y&#x27;; // 特点std::string s = &quot;ME&quot;; // 字符串（文本）bool isRight = true; // 布尔值// 常量const float RATE = 0.8;
int age &#123;25&#125;; // 自 C++11std::cout &lt;&lt; age; // 打印 25
原始数据类型
数据类型 大小 范围
int 4 bytes -231 到 231-1
float 4 bytes N&#x2F;A
double 8 bytes N&#x2F;A
char 1 byte -128 到 127
bool 1 byte true &#x2F; false
void N&#x2F;A N&#x2F;A
wchar_t 2 到 4 bytes 1 个宽字符
用户输入int num;std::cout &lt;&lt; &quot;Type a number: &quot;;std::cin &gt;&gt; num;std::cout &lt;&lt; &quot;You entered &quot; &lt;&lt; num;
交换int a = 5, b = 10;std::swap(a, b);// 输出: a=10, b=5std::cout &lt;&lt; &quot;a=&quot; &lt;&lt; a &lt;&lt; &quot;, b=&quot; &lt;&lt; b;// 整数交换的奇技淫巧(x ^= y), (y ^= x), (x ^= y);// 注意！ 以下操作会造成 undefined behaviorx ^= y ^= x ^= y;
注释// C++中的单行注释/* 这是一个多行注释 在 C++ 中 */
If 语句if (a == 10) &#123; // do something&#125;
查看: 条件 循环for (int i = 0; i &lt; 10; i++) &#123; std::cout &lt;&lt; i &lt;&lt; &quot;\n&quot;;&#125;
查看: 循环 Loops 函数
#include &lt;iostream&gt;void hello(); // 声明int main() &#123; // 主函数 hello(); // 执行函数&#125;void hello() &#123; // 定义 std::cout &lt;&lt; &quot;Hello Quick Reference!\n&quot;;&#125;
查看: 函数 Functions 引用int i = 1;int&amp; ri = i; // ri 是对 i 的引用ri = 2; // i 现在改为 2std::cout &lt;&lt; &quot;i=&quot; &lt;&lt; i;i = 3; // i 现在改为 3std::cout &lt;&lt; &quot;ri=&quot; &lt;&lt; ri;
ri 和 i 指的是相同的内存位置 命名空间#include &lt;iostream&gt;namespace ns1 &#123;int val()&#123;return 5;&#125;&#125;int main()&#123; std::cout &lt;&lt; ns1::val();&#125;
#include &lt;iostream&gt;namespace ns1 &#123;int val()&#123;return 5;&#125;&#125;using namespace ns1;using namespace std;int main()&#123; cout &lt;&lt; val();&#125;
名称空间允许名称下的全局标识符 C++ 数组定义std::array&lt;int, 3&gt; marks; // 定义marks[0] = 92;marks[1] = 97;marks[2] = 98;// 定义和初始化std::array&lt;int, 3&gt; marks = &#123;92, 97, 98&#125;;// 有空成员std::array&lt;int, 3&gt; marks = &#123;92, 97&#125;;std::cout &lt;&lt; marks[2]; // 输出: 0
操控┌─────┬─────┬─────┬─────┬─────┬─────┐| 92 | 97 | 98 | 99 | 98 | 94 |└─────┴─────┴─────┴─────┴─────┴─────┘ 0 1 2 3 4 5
std::array&lt;int, 6&gt; marks = &#123; 92, 97, 98, 99, 98, 94&#125;;// 打印第一个元素std::cout &lt;&lt; marks[0];// 将第 2 个元素更改为 99marks[1] = 99;// 从用户那里获取输入std::cin &gt;&gt; marks[2];
展示char ref[5] = &#123;&#x27;R&#x27;, &#x27;e&#x27;, &#x27;f&#x27;&#125;;// 基于范围的for循环for (const int &amp;n : ref) &#123; std::cout &lt;&lt; std::string(1, n);&#125;// 传统的for循环for (int i = 0; i &lt; sizeof(ref); ++i) &#123; std::cout &lt;&lt; ref[i];&#125;
多维 j0 j1 j2 j3 j4 j5 ┌────┬────┬────┬────┬────┬────┐i0 | 1 | 2 | 3 | 4 | 5 | 6 | ├────┼────┼────┼────┼────┼────┤i1 | 6 | 5 | 4 | 3 | 2 | 1 | └────┴────┴────┴────┴────┴────┘
int x[2][6] = &#123; &#123;1,2,3,4,5,6&#125;, &#123;6,5,4,3,2,1&#125;&#125;;for (int i = 0; i &lt; 2; ++i) &#123; for (int j = 0; j &lt; 6; ++j) &#123; std::cout &lt;&lt; x[i][j] &lt;&lt; &quot; &quot;; &#125;&#125;// 输出: 1 2 3 4 5 6 6 5 4 3 2 1
C++ 条件If Clauseif (a == 10) &#123; // do something&#125;
int number = 16;if (number % 2 == 0)&#123; std::cout &lt;&lt; &quot;even&quot;;&#125;else&#123; std::cout &lt;&lt; &quot;odd&quot;;&#125;// 输出: even
Else if 语句int score = 99;if (score == 100) &#123; std::cout &lt;&lt; &quot;Superb&quot;;&#125;else if (score &gt;= 90) &#123; std::cout &lt;&lt; &quot;Excellent&quot;;&#125;else if (score &gt;= 80) &#123; std::cout &lt;&lt; &quot;Very Good&quot;;&#125;else if (score &gt;= 70) &#123; std::cout &lt;&lt; &quot;Good&quot;;&#125;else if (score &gt;= 60) std::cout &lt;&lt; &quot;OK&quot;;else std::cout &lt;&lt; &quot;What?&quot;;
运算符
关系运算符
:– –
a == b a 等于 b
a != b a 不等于 b
a &lt; b a 小于 b
a &gt; b a 大于 b
a &lt;= b a 小于或等于 b
a &gt;= b a 大于或等于 b
赋值运算符
范例 相当于
a += b Aka a = a + b
a -= b Aka a = a - b
a *= b Aka a = a * b
a /= b Aka a = a / b
a %= b Aka a = a % b
逻辑运算符
Example Meaning
exp1 &amp;&amp; exp2 Both are true (AND)
&#96;exp1
!exp exp is false (NOT)
位运算符
Operator Description
a &amp; b Binary AND
&#96;a b&#96;
a ^ b Binary XOR
a ~ b Binary One’s Complement
a &lt;&lt; b Binary Shift Left
a &gt;&gt; b Binary Shift Right
三元运算符 ┌── True ──┐Result = Condition ? Exp1 : Exp2; └───── False ─────┘
int x = 3, y = 5, max;max = (x &gt; y) ? x : y;// 输出: 5std::cout &lt;&lt; max &lt;&lt; std::endl;
int x = 3, y = 5, max;if (x &gt; y) &#123; max = x;&#125; else &#123; max = y;&#125;// 输出: 5std::cout &lt;&lt; max &lt;&lt; std::endl;
switch 语句int num = 2;switch (num) &#123; case 0: std::cout &lt;&lt; &quot;Zero&quot;; break; case 1: std::cout &lt;&lt; &quot;One&quot;; break; case 2: std::cout &lt;&lt; &quot;Two&quot;; break; case 3: std::cout &lt;&lt; &quot;Three&quot;; break; default: std::cout &lt;&lt; &quot;What?&quot;; break;&#125;
C++ 循环Whileint i = 0;while (i &lt; 6) &#123; std::cout &lt;&lt; i++;&#125;// 输出: 012345
Do-whileint i = 1;do &#123; std::cout &lt;&lt; i++;&#125; while (i &lt;= 5);// 输出: 12345
Continue 语句for (int i = 0; i &lt; 10; i++) &#123; if (i % 2 == 0) &#123; continue; &#125; std::cout &lt;&lt; i;&#125; // 输出: 13579
无限循环while (true) &#123; // true or 1 std::cout &lt;&lt; &quot;无限循环&quot;;&#125;
for (;;) &#123; std::cout &lt;&lt; &quot;无限循环&quot;;&#125;
for(int i = 1; i &gt; 0; i++) &#123; std::cout &lt;&lt; &quot;infinite loop&quot;;&#125;
for_each (C++11 起)#include &lt;iostream&gt;int main()&#123; auto print = [](int num) &#123; std::cout &lt;&lt; num &lt;&lt; std::endl; &#125;; std::array&lt;int, 4&gt; arr = &#123;1, 2, 3, 4&#125;; std::for_each(arr.begin(), arr.end(), print); return 0;&#125;
基于范围 (C++11 起)for (int n : &#123;1, 2, 3, 4, 5&#125;) &#123; std::cout &lt;&lt; n &lt;&lt; &quot; &quot;;&#125;// 输出: 1 2 3 4 5
std::string hello = &quot;Quick Reference.ME&quot;;for (char c: hello)&#123; std::cout &lt;&lt; c &lt;&lt; &quot; &quot;;&#125;// 输出: Q u i c k R e f . M E
中断语句int password, times = 0;while (password != 1234) &#123; if (times++ &gt;= 3) &#123; std::cout &lt;&lt; &quot;Locked!\n&quot;; break; &#125; std::cout &lt;&lt; &quot;Password: &quot;; std::cin &gt;&gt; password; // input&#125;
Several variationsfor (int i = 0, j = 2; i &lt; 3; i++, j--)&#123; std::cout &lt;&lt; &quot;i=&quot; &lt;&lt; i &lt;&lt; &quot;,&quot;; std::cout &lt;&lt; &quot;j=&quot; &lt;&lt; j &lt;&lt; &quot;;&quot;;&#125;// 输出: i=0,j=2;i=1,j=1;i=2,j=0;
autostd:: string s = &quot;hello world&quot;;for(auto c: s)&#123; std:: cout &lt;&lt; c &lt;&lt; &quot; &quot;;&#125;// 输出: h e l l o w o r l d
C++ 函数参数和返回#include &lt;iostream&gt;int add(int a, int b) &#123; return a + b;&#125;int main() &#123; std::cout &lt;&lt; add(10, 20);&#125;
add 是一个接受 2 个整数并返回整数的函数 重载void fun(string a, string b) &#123; std::cout &lt;&lt; a + &quot; &quot; + b;&#125;void fun(string a) &#123; std::cout &lt;&lt; a;&#125;void fun(int a) &#123; std::cout &lt;&lt; a;&#125;
内置函数#include &lt;iostream&gt;#include &lt;cmath&gt; // 导入库int main() &#123; // sqrt() 来自 cmath std::cout &lt;&lt; sqrt(9);&#125;
Lambda 表达式
Lambda 表达式可以在函数内定义，可以理解为在函数内定义的临时函数。格式： auto func = []() -&gt; return_type &#123; &#125;;
[]为捕获列表，能够捕获其所在函数的局部变量
一个空的捕获列表代表Lambda表达式不捕获任何的变量
对于值捕获，直接在中括号中填写要捕获的变量即可： int val = 5;auto func = [val]() -&gt; return_type &#123; &#125;;
对于引用捕获，需要在捕获的变量前添加&amp;： string str(&quot;hello world!&quot;);auto func = [&amp;str]() -&gt; return_type &#123; &#125;;
如果变量太多，需要编译器根据我们编写的代码自动捕获，可以采用隐式捕获的方式。
全部值捕获： int val1, val2;auto func = [=]() -&gt; int &#123; return val1 + val2; &#125;;
全部引用捕获： string str1(&quot;hello&quot;), str2(&quot;word!&quot;);auto func = [&amp;]() -&gt; string &#123; return str1 + str2; &#125;;
混合隐式捕获： 如果希望对一部分变量采用值捕获，对其他变量采用引用捕获，可以混合使用： int val1 = 123, val2 = 456;string str1(&quot;123&quot;), str2(456);auto func1 = [=, &amp;str1]() -&gt; int &#123; return val1 == std::stoi(str1) ? val1 : val2; &#125;;auto func2 = [&amp;, val1]() -&gt; int &#123; return str1 == std::to_string(val1) ? str1 : str2; &#125;;
() 是参数列表，我们只需要按照普通函数的使用方法来使用即可
return_type 是函数的返回类型，-&gt; return_type 可以不写，编译器会自动推导
&#123;&#125; 中的内容就是函数体，依照普通函数的使用方法使用即可
此处给出一个 Lambda 表达式的实际使用例子(当然可以使用 str::copy): // vec中包含1, 2, 3, 4, 5std::vector&lt;int&gt; vec(&#123;1, 2, 3, 4, 5&#125;);std::for_each(vec.begin(), vec.end(), [](int&amp; ele) -&gt; void &#123; std::cout &lt;&lt; ele &lt;&lt; &quot; &quot;; &#125;);
C++多线程多线程介绍g++编译选项：-std=c++11。包含头文件：
#include &lt;thread&gt;：C++多线程库 #include &lt;mutex&gt;：C++互斥量库 #include &lt;future&gt;：C++异步库
线程的创建
以普通函数作为线程入口函数： void entry_1() &#123; &#125;void entry_2(int val) &#123; &#125;std::thread my_thread_1(entry_1);std::thread my_thread_2(entry_2, 5);
以类对象作为线程入口函数： class Entry&#123; void operator()() &#123; &#125; void entry_function() &#123; &#125;&#125;;Entry entry;// 调用operator()()std::thread my_thread_1(entry);// 调用Entry::entry_functionstd::thread my_thread_2(&amp;Entry::entry_function, &amp;entry);
以lambda表达式作为线程入口函数： std::thread my_thread([]() -&gt; void &#123; // ... &#125;);
线程的销毁thread my_thread;// 阻塞my_thread.join();// 非阻塞my_thread.detach();
this_thread// 获取当前线程IDstd::this_thread::get_id();// 使当前线程休眠一段指定时间std::this_thread::sleep_for();// 使当前线程休眠到指定时间std::this_thread::sleep_until();// 暂停当前线程的执行，让别的线程执行std::this_thread::yield();
锁
#include &lt;mutex&gt;
锁的基本操作创建锁 std::mutex m;
上锁 m.lock();
解锁 m.unlock();
尝试上锁：成功返回true，失败返回false m.try_lock();
解锁 m.unlock();
更简单的锁 —— std::lock_guard&lt;Mutex&gt;构造时上锁，析构时解锁 std::mutex m;std::lock_guard&lt;std::mutex&gt; lock(m);
额外参数：std::adopt_lock：只需解锁，无需上锁 // 手动上锁m.lock();std::lock_guard&lt;mutex&gt; lock(m, std::adopt_lock);
unique_lock&lt;Mutex&gt;构造上锁，析构解锁 std::mutex m;std::unique_lock&lt;mutex&gt; lock(m);
std::adopt_lock只需解锁，无需上锁 // 手动上锁m.lock();std::unique_lock&lt;mutex&gt; lock(m, std::adopt_lock);
std::try_to_lock尝试上锁，可以通过std::unique_lock&lt;Mutex&gt;::owns_lock()查看状态 std::unique_lock&lt;mutex&gt; lock(m, std::try_to_lock);if (lock.owns_lock())&#123; // 拿到了锁&#125;else&#123; // 没有&#125;
std::defer_lock绑定锁，但不上锁 std::unique_lock&lt;mutex&gt; lock(m, std::defer_lock);lock.lock();lock.unlock();
std::unique_lock&lt;Mutex&gt;::release返回所管理的mutex对象指针，**释放所有权。**一旦释放了所有权，那么如果原来互斥量处于互斥状态，程序员有责任手动解锁。 std::call_once当多个线程通过这个函数调用一个可调用对象时，只会有一个线程成功调用。 std::once_flag flag;void foo() &#123; &#125;std::call_once(flag, foo);
std::condition_variable创建条件变量std::condition_variable cond;
等待条件变量被通知std::unique_lock&lt;std::mutex&gt; lock;extern bool predicate();// 调用方式 1cond.wait(lock);// 调用方式 2cond.wait(lock, predicate);
wait不断地尝试重新获取并加锁该互斥量，如果获取不到，它就卡在这里并反复尝试重新获取，如果获取到了，执行流程就继续往下走 wait在获取到互斥量并加锁了互斥量之后： 如果wait被提供了可调用对象，那么就执行这个可调用对象： 如果返回值为false，那么wait继续加锁，直到再次被 notified 如果返回值为true，那么wait返回，继续执行流程
如果wait没有第二个参数，那么直接返回，继续执行
std::condition_variable::notify_onenotify_one 唤醒一个调用 wait 的线程。注意在唤醒之前要解锁，否则调用 wait 的线程也会因为无法加锁而阻塞。 std::condition_variable::notify_all唤醒所有调用 wait 的线程。 获取线程的运行结果
#include &lt;future&gt;
创建异步任务double func(int val);// 使用std::async创建异步任务// 使用std::future获取结果// future模板中存放返回值类型std::future&lt;double&gt; result = std::async(func, 5);
获取异步任务的返回值等待异步任务结束，但是不获取返回值： result.wait();
获取异步任务的返回值： int val = result.get();
注：
get()返回右值，因此只可调用一次 只要调用上述任意函数，线程就会一直阻塞到返回值可用（入口函数运行结束）
std::async 的额外参数额外参数可以被放在 std::async 的第一个参数位置，用于设定 std::async 的行为：
std::launch::deferred：入口函数的运行会被推迟到std::future&lt;T&gt;::get()或者std::future&lt;T&gt;::wait()被调用时。此时调用线程会直接运行线程入口函数，换言之，不会创建子线程 std::launch::async：立即创建子线程，并运行线程入口函数 std::launch::deferred | std::launch::async：默认值，由系统自行决定
返回值的状态让当前线程等待一段时间（等待到指定时间点），以期待返回值准备好： extern double foo(int val) &#123;&#125;std::future&lt;double&gt; result = async(foo, 5);//返回值类型std::future_status status;// 等待一段时间status = result.wait_for( std::chrono::seconds(1) );// 等待到某一时间点status = result.wait_for( std::chrono::now() + std::chrono::seconds(1) );
在指定的时间过去后，可以获取等待的结果： // 返回值已经准备好if (status == std::future_status::ready)&#123;&#125;// 超时：尚未准备好else if (status == std::future_status::timeout)&#123; &#125;// 尚未启动: std::launch::deferredelse if (status == std::future_status::deferred)&#123; &#125;
多个返回值如果要多次获取结果，可以使用std::shared_future，其会返回结果的一个拷贝。 std::shared_future&lt;T&gt; result;
对于不可拷贝对象，可以在std::shared_future中存储对象的指针，而非指针本身。 创建线程void threadFunction() &#123; // 线程函数体 std::cout &lt;&lt; &quot;From thread&quot; &lt;&lt; std::endl;&#125;int main() &#123; // 创建线程并开始执行线程函数 std::thread t(threadFunction); // 等待线程执行完毕 t.join(); return 0;&#125;
传递参数给线程函数void threadFunction(int value) &#123; // 线程函数体 std::cout &lt;&lt; &quot;Received value: &quot; &lt;&lt; value &lt;&lt; std::endl;&#125;int main() &#123; int data = 42; std::thread t(threadFunction, data); t.join(); return 0;&#125;
使用Lambda表达式创建线程int main() &#123; int data = 42; std::thread t([data]() &#123; // Lambda 表达式作为线程函数 std::cout &lt;&lt; &quot;Received value: &quot; &lt;&lt; data &lt;&lt; std::endl; &#125;); t.join(); return 0;&#125;
处理线程间的同步：#include &lt;mutex&gt;std::mutex mtx;void threadFunction() &#123; std::lock_guard&lt;std::mutex&gt; lock(mtx); std::cout &lt;&lt; &quot;Thread safe output.&quot; &lt;&lt; std::endl;&#125;int main() &#123; std::thread t1(threadFunction); std::thread t2(threadFunction); t1.join(); t2.join(); return 0;&#125;
使用std::async启动异步任务：#include &lt;future&gt;int taskFunction() &#123; // 异步任务 return 42;&#125;int main() &#123; // 启动异步任务 std::future&lt;int&gt; fut = std::async(std::launch::async, taskFunction); // 获取异步任务的结果 int result = fut.get(); std::cout &lt;&lt; &quot;Result: &quot; &lt;&lt; result &lt;&lt; std::endl; return 0;&#125;
C++ 预处理器预处理器
if elif else endif ifdef ifndef define undef include line error pragma defined __has_include __has_cpp_attribute export import module
Includes#include &quot;iostream&quot;#include &lt;iostream&gt;
Defines#define FOO#define FOO &quot;hello&quot;#undef FOO
If
#ifdef DEBUG console.log(&#x27;hi&#x27;);#elif defined VERBOSE ...#else ...#endif
Error#if VERSION == 2.0 #error Unsupported #warning Not really supported#endif
宏#define DEG(x) ((x) * 57.29)
令牌连接#define DST(name) name##_s name##_tDST(object); #=&gt; object_s object_t;
字符串化#define STR(name) #namechar * a = STR(object); #=&gt; char * a = &quot;object&quot;;
文件和行#define LOG(msg) console.log(__FILE__, __LINE__, msg)#=&gt; console.log(&quot;file.txt&quot;, 3, &quot;hey&quot;)
各种各样的转义序列
转义序列 说明
\b 退格键
\f 换页
\n 换行
\r 返回
\t 水平制表符
\v 垂直制表符
\\ 反斜杠
\&#39; 单引号
\&quot; 双引号
\? 问号
\0 空字符
关键字
alignas alignof and and_eq asm atomic_cancel atomic_commit atomic_noexcept auto bitand bitor bool break case catch char char8_t char16_t char32_t class compl concept const consteval constexpr constinit const_cast continue co_await co_return co_yield decltype default delete do double dynamic_cast else enum explicit export extern false float for friend goto if inline int long mutable namespace new noexcept not not_eq nullptr operator or or_eq private protected public reflexpr register reinterpret_cast requires return short signed sizeof static static_assert static_cast struct switch synchronized template this thread_local throw true try typedef typeid typename union unsigned using virtual void volatile wchar_t while xor xor_eq final override transaction_safe transaction_safe_dynamic
预处理器 if elif else endif ifdef ifndef define undef include line error pragma defined __has_include __has_cpp_attribute export import module
另见 C++ Infographics &amp; Cheat Sheets (hackingcpp.com) C++ reference (cppreference.com) C++ Language Tutorials (cplusplus.com)

CSS 备忘清单这是一份关于 CSS 优点的快速参考备忘单，列出了选择器语法、属性、单位和其他有用的信息 入门介绍
CSS 功能丰富，不仅仅是布局页面 外部样式表 &lt;link&gt;&lt;/link&gt;&lt;link href=&quot;./path/to/stylesheet/style.css&quot; rel=&quot;stylesheet&quot; type=&quot;text/css&quot;&gt;
内部样式表 &lt;style&gt;&lt;style&gt; body &#123; background-color: linen; &#125;&lt;/style&gt;
内联样式 style&lt;h2 style=&quot;text-align: center;&quot;&gt; 居中文本&lt;/h2&gt;&lt;p style=&quot;color: blue; font-size: 18px;&quot;&gt; 蓝色，18像素文本&lt;/p&gt;
添加 class 类&lt;div class=&quot;classname&quot;&gt;&lt;/div&gt;&lt;div class=&quot;class1 ... classn&quot;&gt;&lt;/div&gt;
支持一个元素上的多个类 !important.post-title &#123; color: blue !important;&#125;
覆盖所有以前的样式规则 选择器h1 &#123; &#125; #job-title &#123; &#125;div.hero &#123; &#125;div &gt; p &#123; &#125;
