Null$a = null;$b = &#x27;Hello php!&#x27;;echo $a ?? &#x27;a is unset&#x27;; # =&gt; a is unsetecho $b ?? &#x27;b is unset&#x27;; # =&gt; Hello php$a = array();$a == null # =&gt; true$a === null # =&gt; falseis_null($a) # =&gt; false
